def magic_items():
    result=[]
    def dependencies(value):
        if isinstance(value,str):return [value] if value.startswith(('phb2014:spell:','mm2014:creature:','dmg2014:magic-item:','dmg2014:rule:')) else []
        if isinstance(value,list):return [i for v in value for i in dependencies(v)]
        if isinstance(value,dict):return [i for v in value.values() for i in dependencies(v)]
        return []
    for index,name,it,pages,category,rarity,attunement,activation,requirement,effect,summary in ROWS:
        effect=deepcopy(effect)
        if 'sentience' in effect:effect['sentienceRuleId']='dmg2014:rule:sentient-magic-items'
        if 'randomProperties' in effect:
            effect['artifactRuleId']='dmg2014:rule:artifacts'
            properties=effect['randomProperties']
            effect['randomPropertyTableIds']=['dmg2014:rule:'+table for key,table in [('minorBeneficial','artifact-minor-beneficial'),('majorBeneficial','artifact-major-beneficial'),('minorDetrimental','artifact-minor-detrimental'),('majorDetrimental','artifact-major-detrimental')] if properties.get(key)]
        e=record('magic-item',index,name,it,pages,{'category':category,'rarity':rarity,'requiresAttunement':attunement,'activation':activation,'usageRequirement':requirement,'effect':effect},summary,book='dmg')
        e['sources'][0]['verification']='read-local-render'
        if index=='dwarven-thrower':
            e['mechanics']['attunementPrerequisites']={'race':'dwarf'};e['fieldSources']['attunementPrerequisites']=[0]
        if index in ['blackrazor','moonblade','wave','whelm']:
            prerequisite_keys=['requiresAlignment','requiresRacesAny','requiresRace','requiresWorship','requiredAttunementRitualLocations','choosesMaster']
            e['mechanics']['attunementPrerequisites']={k:effect[k] for k in prerequisite_keys if k in effect};e['fieldSources']['attunementPrerequisites']=[0]
